// ================== CONFIGURACIÓN DEL CLIENTE ==================
const CONFIG = {
  crm_url: 'https://crm.aikonintelligence.com',
  tenant_id: 'PEGAR_TENANT_ID_DEL_CLIENTE',
  webhook_secret: 'PEGAR_SECRETO_COMPARTIDO',
  // Webhook del bot de ESTE cliente (puede estar en otro n8n)
  bot_webhook_url: 'PEGAR_URL_DEL_WEBHOOK_DEL_BOT',
};
// ===============================================================

// Convierte el webhook de YCloud al formato estándar del CRM.
const STATUS = { accepted: 'sent', sent: 'sent', delivered: 'delivered', read: 'read', failed: 'failed' };
const out = [];
for (const item of $input.all()) {
  const e = item.json.body ?? item.json;

  // Estado de un mensaje enviado
  if (e.type === 'whatsapp.message.updated' && e.whatsappMessage) {
    const s = e.whatsappMessage;
    if (!STATUS[s.status]) continue;
    out.push({ json: { kind: 'status', config: CONFIG, crm: {
      action: 'message_status',
      tenant_id: CONFIG.tenant_id,
      wa_message_id: s.wamid ?? s.id,
      status: STATUS[s.status],
      error_code: s.errorCode ? String(s.errorCode) : null,
      error_message: s.errorMessage ?? null,
    } } });
    continue;
  }

  // Mensaje del cliente
  const m = e.whatsappInboundMessage;
  if (e.type !== 'whatsapp.inbound_message.received' || !m) continue;
    let content = null;
    let contentType = m.type;
    let buttonText = null;
    let buttonPayload = null;
    switch (m.type) {
      case 'text': content = m.text?.body ?? null; break;
      case 'image': case 'video': case 'document': case 'audio': case 'sticker':
        content = m[m.type]?.caption ?? null;
        break;
      case 'location': content = m.location ? m.location.latitude + ',' + m.location.longitude : null; break;
      case 'reaction': content = m.reaction?.emoji ?? null; break;
      case 'button':
        buttonText = m.button?.text ?? null; buttonPayload = m.button?.payload ?? null;
        content = buttonText; contentType = 'text';
        break;
      case 'interactive':
        buttonText = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? null;
        buttonPayload = m.interactive?.button_reply?.id ?? m.interactive?.list_reply?.id ?? null;
        content = buttonText; contentType = 'text';
        break;
      default: contentType = 'text'; content = '[' + m.type + ']';
    }
    const media = ['image', 'video', 'document', 'audio', 'sticker'].includes(m.type) ? m[m.type] ?? {} : {};
  out.push({ json: { kind: 'message', config: CONFIG, media_id: media.id ?? null, media_link: media.link ?? null, crm: {
    action: 'inbound_message',
    tenant_id: CONFIG.tenant_id,
    wa_id: String(m.from ?? '').replace(/\D/g, ''),
    contact_name: m.customerProfile?.name ?? null,
    wa_message_id: m.wamid ?? m.id,
    content,
    content_type: contentType,
    button_text: buttonText,
    button_payload: buttonPayload,
    media_mime_type: media.mime_type ?? null,
    media_filename: m.document?.filename ?? null,
  } } });
}
return out;

// Sube el archivo descargado al CRM (bucket chat-media) y deja el binario para Gemini.
const out = [];
const items = $input.all();
const bases = $('¿Tiene archivo?').all(0);
for (let i = 0; i < items.length; i++) {
  const base = bases[i]?.json ?? bases[0].json;
  const cfg = base.config;
  const bin = items[i].binary?.data;
  const crm = { ...base.crm };
  if (!bin) {
    // No se pudo descargar: se guarda el mensaje sin archivo
    out.push({ json: { ...base, crm, download_failed: true }, pairedItem: { item: i } });
    continue;
  }
  const mime = String(bin.mimeType || crm.media_mime_type || 'application/octet-stream').split(';')[0].trim();
  bin.mimeType = mime;
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    const up = await this.helpers.httpRequest({
      method: 'POST',
      url: cfg.crm_url + '/api/webhooks/n8n',
      headers: { 'x-webhook-secret': cfg.webhook_secret },
      body: { action: 'media_upload_url', tenant_id: cfg.tenant_id, mime_type: mime, filename: crm.media_filename || bin.fileName },
      json: true,
    });
    if (buffer.length <= up.max_bytes) {
      await this.helpers.httpRequest({ method: 'PUT', url: up.upload_url, body: buffer, headers: { 'Content-Type': mime } });
      crm.media_url = up.public_url;
    }
  } catch (err) {
    crm.media_url = null;
  }
  crm.media_mime_type = mime;
  out.push({ json: { ...base, crm }, binary: { data: bin }, pairedItem: { item: i } });
}
return out;

// Une el resultado de Gemini con el mensaje: primera línea = etiqueta, debajo la transcripción o descripción.
let base;
try { base = $('Subir archivo al CRM').item.json; } catch (e) { base = $('Subir archivo al CRM').first().json; }
const r = $json ?? {};

// El nodo de Gemini puede devolver el texto en distintos campos: se toma el primero que exista
function geminiText(o) {
  if (!o || typeof o !== 'object') return '';
  if (typeof o.text === 'string') return o.text;
  if (Array.isArray(o.content?.parts)) return o.content.parts.map((p) => p.text || '').join('');
  if (Array.isArray(o.candidates)) return geminiText(o.candidates[0]);
  if (typeof o.content === 'string') return o.content;
  if (typeof o.output === 'string') return o.output;
  return '';
}
const result = (r.error ? '' : geminiText(r).trim()) || '(no se pudo leer el contenido)';
const crm = { ...base.crm };
const caption = String(crm.content || '').trim();
const withCaption = (t) => (caption ? 'Texto del cliente: ' + caption + (t ? '\n' + t : '') : t);

let label = null;
let body = caption;
switch (crm.content_type) {
  case 'audio':
    label = 'Nota de voz del cliente (transcripción automática)';
    body = result;
    break;
  case 'image':
    label = 'Imagen enviada por el cliente (descripción automática)';
    body = withCaption(result);
    break;
  case 'sticker':
    label = 'Sticker enviado por el cliente';
    body = result;
    break;
  case 'document':
    label = 'Documento enviado por el cliente: ' + (crm.media_filename || 'archivo');
    body = withCaption(result.slice(0, 4000));
    break;
  case 'video':
    label = 'Video enviado por el cliente (descripción automática)';
    body = withCaption(result);
    break;
}
if (base.download_failed) body = withCaption('(no se pudo descargar el archivo)');
if (label && !body) body = '(no se pudo leer el contenido)';
crm.content = label ? '[' + label + ']\n' + body : body;

const { download_failed, ...rest } = base;
return { json: { ...rest, crm } };
